SELECT 

WHERE d.kind = #{kind}
AND d.doc_no LIKE CONCAT('%', #{q.docNo}, '%')
AND o.order_no LIKE CONCAT('%', #{q.orderNo}, '%')
AND d.order_id = #{q.orderId}
AND d.partner_id = #{q.partnerId}

AND EXISTS (SELECT 1 FROM scm_trade_doc_item ti
    WHERE ti.doc_id = d.id AND COALESCE(ti.warehouse_id, d.warehouse_id) = #{q.warehouseId})
AND d.biz_date >= #{q.beginDate}
AND d.biz_date <= #{q.endDate}
ORDER BY d.id DESC
